head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/calendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
scwin.gDepCd;
scwin.gEmpNo;
scwin.questNo;
scwin.gLodingYn = 'N';
scwin.gIsurCd;
scwin.gParamObj = new Array(2);
scwin.vScrenID = "ULDSTF30323.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Init = function() {
    scwin.questNo = $c.stf.getQuery(frame.srcUrl, "QUEST_NO");
    //alert('[questNo]'+questNo);

};
scwin.fn_read = function() {
    trs_Read.Action = "/QuestionMgt.do?method=readQuestionResult&questNo=" + scwin.questNo + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    trs_Read.KeyName = "toinb_dataid4";
    trs_Read.KeyValue = "JSP(O:pOutput1=dts_Quest,O:pOutput2=dts_QuestResult)";
    trs_Read.Post();
};
scwin.fn_search = function() {
    var comCd = txb_isur_cd.getValue();
    var depCd = cmb_depList.BindColVal;
    var empCd = cmb_EmpList.BindColVal;
    var startDate = edt_SDate.getValue();
    var endDate = edt_EDate.getValue();
    if (empCd == "") {
        empCd = '%';
    }
    scwin.gLodingYn = 'Y';
    $c.cm.ShowWin(grd_tmp_1);
    var url = "/QuestionMgt.do?method=searchQuestionResultList&inputMessageId=BIZSPT_RESULT_COM_INOUT&outputMessageId=BIZSPT_RESULT_COM_INOUT";
    url += "&questNo=" + scwin.questNo;
    url += "&comCd=" + comCd;
    url += "&depCd=" + depCd;
    url += "&empNo=" + empCd;
    url += "&startDate=" + startDate;
    url += "&endDate=" + endDate;
    url += "&prog_stat_cd=" + $c.stf.getObjectValue(rdo_QUEST_PROG_STAT_CD);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_QuestResult.DataID = encodeURI(url);
    dts_QuestResult.reset();
};
scwin.roundMode = function(v, scale) {
    var p = Math.pow(10, scale);
    return Math.round(v * p) / p;
};
scwin.fn_quesInfo = function() {
    var url = "/QuestionMgt.do?method=resultviewQues&inputMessageId=BIZSPT_RESULT_QUES_INOUT&outputMessageId=BIZSPT_RESULT_QUES_INOUT&questNo=" + scwin.questNo + "&DIV=1";
    dts_QuestResultQues.DataID = encodeURI(url);
    dts_QuestResultQues.reset();
};
scwin.fn_SetGridHeader = function() {
    var headerStr = "ISUR_CD:String,COM_NM:String,DEP_NM:String,EMP_NM:String,ANS_DD:String";
    var FormatStr = "";
    var basic = "<C>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "bgcolor='{decode(currow-tointeger(currow/2)*2,0,'#f2f5f9',1,'#ffffff')}' ";
    basic += "name='법인코드' id='ISUR_CD' show='true' </C>";
    basic += "<C>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "bgcolor='{decode(currow-tointeger(currow/2)*2,0,'#f2f5f9',1,'#ffffff')}' ";
    basic += "name='법인명' id='COM_NM' show='true' </C>";
    basic += "<C>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "bgcolor='{decode(currow-tointeger(currow/2)*2,0,'#f2f5f9',1,'#ffffff')}' ";
    basic += "name='담당팀' id='DEP_NM' show='true' </C>";
    basic += "<C>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "bgcolor='{decode(currow-tointeger(currow/2)*2,0,'#f2f5f9',1,'#ffffff')}' ";
    basic += "name='담당자' id='EMP_NM' show='true' </C>";
    basic += "<C>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "bgcolor='{decode(currow-tointeger(currow/2)*2,0,'#f2f5f9',1,'#ffffff')}' ";
    basic += "name='응답일자' id='ANS_DD' show='true' </C>";
    FormatStr += basic;
    for (var i = 1; i <= dts_QuestResultQues.getTotalRow(); i++) {
        // head append start.
        var css_str = "<C>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
        css_str += "headbgcolor='#598fd5' headcolor='#ffffff' ";
        css_str += "bgcolor='{decode(currow-tointeger(currow/2)*2,0,'#f2f5f9',1,'#ffffff')}' ";
        css_str += "name='" + (dts_QuestResultQues.getCellData(i, "QUES_CONTN")).replace(/'/g, "") + "' id='" + "ANS" + i + "' show='true' </C>";
        FormatStr += css_str;
        headerStr = headerStr + ",ANS" + i + ":String";
    }

    //alert(FormatStr);
    grd_Grid.setDisabled(true);
    grd_Grid.Format = FormatStr;
    grd_Grid.className = "Grid_01";
    grd_Grid.FillArea = "true";
    grd_Grid.AutoResizingWithHeader = "true";
    //dts_QuestResultAns.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_QuestResultAns.insertRow();
    dts_QuestResultAns.setCellData(dts_QuestResultAns.getRowPosition(), "COM_NM", "AAAAA");
    var depCd = cmb_depList.BindColVal;
    var empCd = cmb_EmpList.BindColVal;

    //실제 데이터 조회
    trs_Read.Action = "/QuestionMgt.do?method=resultviewQuesAns&questNo=" + scwin.questNo + "&depCd=" + depCd + "&empCd=" + empCd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    trs_Read.KeyName = "toinb_dataid4";
    trs_Read.KeyValue = "JSP(I:pOutput=dts_QuestResultAns,O:pOutput=dts_QuestResultAns)";
    trs_Read.Post();
    $c.cp.removeRow(dts_QuestResultAns, 1);
};
scwin.fn_Save = function() {
    if (dts_QuestResult.getTotalRow() == 0) {
        $c.win.alert("대상을 선택하세요");
        return;
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", '저장'))) return;
    scwin.fn_trs();
};
scwin.fn_trs = function() {
    //alert('dts_QuestResult'+dts_QuestResult);
    trs_Save.Action = "/QuestionMgt.do?method=updateRemkQuestion" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_QuestResult)";
    trs_Save.Post();
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gIsurCd = dts_QuestResult.getCellData(eval(obj), "ISUR_CD");
    //alert("부모창:"+ gIsurCd);

};
scwin.fn_openSendMail = function() {
    if (js_svrGubun == 'dr') {
        $c.win.alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
        return;
    }
    var url = "";
    url = "/bizspt/ULDSTF30325.gfm?";
    url += "QUEST_NO=" + scwin.questNo;
    url += "&frameID=" + frame.FrameID;
    if (scwin.fn_setParam(scwin.questNo)) {
        // formal arguments
        $c.frame.path("../../").GWinOpen("ULDSTF30325", url, "이메일 신규", 200, 10, 790, 730 + 30, "");
    }
};
scwin.fn_setParam = function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) == "undefined") {
        $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    var argv = fn_setParam.arguments;
    var argc = fn_setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (var i = 0; i < argc; i++) {
        // actual arguments
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};
scwin.grd_tmp_1_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.btn_Mail_onclick = function() {
    scwin.fn_openSendMail();
};
scwin.grd_tmp_1_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "COM_NM") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.txb_isur_cd_onblur = function() {
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.icn_SCal_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.icn_ECal_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.cmb_depList_OnSelChange = function() {
    scwin.gDepCd = $c.stf.trim($c.cp.valueOfIndex(cmb_depList, "VALUE", cmb_depList.getSelectedIndex()));
    dts_emp.UseFilter = true;
    dts_emp.Filter();
};
scwin.dts_emp_OnLoadError = function() {
    $c.stf.alert_error(dts_emp);
};
scwin.dts_dep_OnLoadError = function() {
    $c.stf.alert_error(dts_dep);
};
scwin.dts_Quest_OnLoadError = function() {
    $c.stf.alert_error(dts_Quest);
};
scwin.dts_QuestResult_OnLoadError = function() {
    $c.stf.alert_error(dts_QuestResult);
};
scwin.dts_QuestResultQues_OnLoadError = function() {
    $c.stf.alert_error(dts_QuestResultQues);
};
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(cmb_TeamList, js_dep_cd);
};
scwin.dts_QuestResultQues_OnLoadCompleted = function(rowcount) {
    scwin.fn_SetGridHeader();
};
scwin.dts_QuestResult_OnLoadCompleted = function(rowcount) {
    if (scwin.gLodingYn == 'Y') {
        $c.cm.CloseWin(rowcount, grd_tmp_1); //조회완료시 LOADING 이미지 종료

    }
    if (dts_QuestResult.ErrorMsg) {
        $c.win.alert(dts_QuestResult.ErrorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
};
scwin.dts_Quest_OnLoadCompleted = function(rowcount) {
    var isurCnt = dts_Quest.getCellData(dts_Quest.getRowPosition(), "ISUR_CD_CNT");
    var resultCnt = dts_Quest.getCellData(dts_Quest.getRowPosition(), "RESULT_CD_CNT");
    var noResultCnt = eval(isurCnt) - eval(resultCnt);
    var questRate = eval(resultCnt) / eval(isurCnt) * 100;
    //비응답회사수
    dts_Quest.setCellData(dts_Quest.getRowPosition(), "NO_QUES_COM", noResultCnt);
    dts_Quest.setCellData(dts_Quest.getRowPosition(), "QUEST_RATE", scwin.roundMode(questRate, 1) + "%");
    var questStat = dts_Quest.getCellData(dts_Quest.getRowPosition(), "QUEST_STAT_CD");
    /*
    if(questStat == "0"){
    	questStat = "설문진행전(작성중)";
    }
    else if (questStat == "1") {
    	questStat = "설문종료";
    }
    else if (questStat == "3") {
    	questStat = "설문중지";
    }
    else if(questStat == "2"){
    	questStat = "설문진행중";
    }
    else{
    	questStat = "설문미진행";
    }
    txb_questStat.value = "(진행상태:  " + questStat + ")";
    */
    if (dts_Quest.getCellData(dts_Quest.getRowPosition(), "RESULT_CD_CNT") > 0) {
        //응답회사가 있을경우 호출
        scwin.fn_quesInfo();
    }
};
scwin.dts_dep_OnLoadCompleted = function(rowcount) {

};
scwin.cmb_depList_OnSelChange = function() {
    scwin.gDepCd = $c.stf.trim($c.cp.valueOfIndex(cmb_depList, "VALUE", cmb_depList.getSelectedIndex()));
    dts_emp.UseFilter = true;
    dts_emp.Filter();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_search();
    scwin.fn_SetGridHeader();
};
scwin.btn_Quest_Excel_onclick = function() {
    if (dts_Quest.getCellData(dts_Quest.getRowPosition(), "RESULT_CD_CNT") > 0) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_Grid, "설문결과", "", "8");
    } else {
        $c.win.alert("[설문에 응답한 회사가] 없습니다.");
    }
};
scwin.btn_Excel_onclick = function() {
    $c.data.downloadGridViewExcel(grd_tmp_1, "설문회사목록", "", "8");
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        Grd_com_isur.style.left = "95px";
        Grd_com_isur.style.top = "203px";
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert("성공적으로 처리 되었습니다.");
    scwin.fn_search();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert('저장이 실패하였습니다.');
    //alert(trs_Save.ErrorMsg);

};
scwin.trs_Read_OnFail = function() {
    $c.win.alert(trs_Read.ErrorMsg);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    $c.cm.PanelToGroupBox(panel_Top1);
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp.Reset();
    scwin.fn_Init();
    /*
    var getQuestNo= frame.Provider("../").fn_getQuestNo; 
    questNo = getQuestNo();
    */

    scwin.fn_read();
    edt_SDate.setValue(dts_Quest.getCellData(dts_Quest.getRowPosition(), "QUEST_STRT_DD"));
    edt_EDate.setValue(dts_Quest.getCellData(dts_Quest.getRowPosition(), "QUEST_END_DD"));
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
};
